1	package relayproof
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9		"testing"
10	)
11	
12	// Regression coverage for the output end that acknowledges only a prefix of
13	// the final result batch and then returns a nil error. A Writer that reports
14	// (n < len(p), nil) breaks the io.Writer contract, but the shutdown flush is
15	// the only write for a short-log stream (records stay buffered), so the
16	// interruption must be surfaced as a stream write failure rather than normal
17	// completion. The two channels NormalizeReader offers its caller stay
18	// independent: a nil output error does not prove the batch arrived whole,
19	// and the invalid-log count is a property of processed input, never a count
20	// of the failure records that made it to the output.
21	//
22	// Everything is scripted in-process (scriptReader/failWriter family plus the
23	// nilErrorPrefixWriter below), so the boundary reproduces deterministically
24	// without real pipes, networks, or device failures.
25	
26	// nilErrorPrefixWriter accepts at most allowBytes bytes across all Write
27	// calls, records everything accepted, and always returns a nil error — even
28	// when it accepts nothing or only a prefix of the offered bytes. This models
29	// an output end that goes away mid-batch without setting the error value
30	// (an io.Writer contract violation that callers must still survive): a
31	// well-behaved sink must turn the short acknowledgement into io.ErrShortWrite
32	// instead of taking the nil error as proof that delivery completed.
33	type nilErrorPrefixWriter struct {
34		buf        bytes.Buffer
35		allowBytes int
36		writes     int
37	}
38	
39	func (w *nilErrorPrefixWriter) Write(p []byte) (int, error) {
40		w.writes++
41		if w.allowBytes <= 0 {
42			return 0, nil
43		}
44		n := len(p)
45		if n > w.allowBytes {
46			n = w.allowBytes
47		}
48		w.buf.Write(p[:n])
49		w.allowBytes -= n
50		return n, nil
51	}
52	
53	// shortWriteBatchInput builds a small batch of short logs: valid logs around
54	// a single field-invalid complete line. The blank line keeps a physical line
55	// number but emits nothing.
56	func shortWriteBatchInput() string {
57		return validLog("a") + "\n" +
58			"\n" +
