261	// nilShortThenRecoverWriter returns a nil-error short acknowledgement on its
262	// first Write and would fully accept every later offer. A correct run must
263	// never take the later offers: the anomaly is a deterministic failure, not a
264	// reason to wait for the output end to recover.
265	type nilShortThenRecoverWriter struct {
266		buf         bytes.Buffer
267		firstAccept int // bytes acknowledged on the first (short, nil) Write
268		writes      int
