271	func (w *nilShortThenRecoverWriter) Write(p []byte) (int, error) {
272		w.writes++
273		if w.writes == 1 {
274			n := w.firstAccept
275			if n >= len(p) {
276				n = len(p) - 1
277			}
278			w.buf.Write(p[:n])
279			return n, nil
280		}
281		w.buf.Write(p)
282		return len(p), nil
283	}
