292		var healthy bytes.Buffer
293		if _, err := NormalizeReader(strings.NewReader(line+"\n"), &healthy); err != nil {
294			t.Fatalf("test setup: healthy reference run failed: %v", err)
295		}
296	
297		for _, firstAccept := range []int{0, 120, len(rec) - 3} {
298			t.Run(fmt.Sprintf("first_accept_%d", firstAccept), func(t *testing.T) {
299				w := &nilShortThenRecoverWriter{firstAccept: firstAccept}
300				failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
301				if err == nil || !errors.Is(err, ErrLogWrite) || !errors.Is(err, io.ErrShortWrite) {
302					t.Fatalf("the first nil short acknowledgement must end the run as a short write, got %v", err)
303				}
304				if failures != 0 {
305					t.Fatalf("a legal long log must not become a failure, got %d", failures)
306				}
307				if w.writes != 1 {
308					t.Fatalf("the run must not retry an output that later could receive, got %d writes", w.writes)
309				}
310				if w.buf.Len() != firstAccept {
311					t.Fatalf("only the initially acknowledged prefix may remain, got %d bytes, want %d", w.buf.Len(), firstAccept)
312				}
313				if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
314					t.Fatalf("retained bytes must be the healthy output prefix:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
315				}
316			})
317		}
318	}
319	
320	// An output end that reports a concrete error on a long write keeps that
321	// error as the write failure's original cause: it must not be replaced by
322	// io.ErrShortWrite, whether it accepted nothing or a non-empty prefix first.
323	func TestNormalizeIOLongResultConcreteWriteErrorStaysCause(t *testing.T) {
324		line := bigSourcedLog("long-a", "")
325	
326		t.Run("nothing accepted, concrete error", func(t *testing.T) {
327			w := &failWriter{err: errSimulatedWrite}
328			failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
329			if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
330				t.Fatalf("want ErrLogWrite wrapping the concrete cause, got %v", err)
331			}
332			if errors.Is(err, io.ErrShortWrite) {
333				t.Fatalf("a concrete write error must not be replaced by io.ErrShortWrite: %v", err)
334			}
335			if failures != 0 {
336				t.Fatalf("the legal long log must not become a failure, got %d", failures)
337			}
338		})
339	
340		t.Run("prefix accepted, then concrete error", func(t *testing.T) {
341			w := &failWriter{partial: 120, err: errSimulatedWrite}
342			failures, err := NormalizeReader(strings.NewReader(line+"\n"), w)
343			if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
344				t.Fatalf("want ErrLogWrite wrapping the concrete cause, got %v", err)
345			}
346			if errors.Is(err, io.ErrShortWrite) {
347				t.Fatalf("a concrete error after a prefix must not become io.ErrShortWrite: %v", err)
348			}
349			if failures != 0 {
350				t.Fatalf("the legal long log must not become a failure, got %d", failures)
351			}
352			if w.buf.Len() != 120 {
353				t.Fatalf("the 120 bytes accepted before the error must remain, got %d", w.buf.Len())
354			}
355		})
356	}
357	
358	// On healthy output the long event completes normally, including its long
359	// extension evidence: processing runs to clean EOF with nil error, the event
360	// is valid, and event.extra carries the input's pad field verbatim.
361	func TestNormalizeIOLongResultFullDeliveryCompletes(t *testing.T) {
362		line := bigSourcedLog("long-a", "")
363		var out bytes.Buffer
364		failures, err := NormalizeReader(strings.NewReader(line+"\n"), &out)
365		if err != nil {
366			t.Fatalf("fully acknowledged long output must complete with nil error, got %v", err)
367		}
368		if failures != 0 {
369			t.Fatalf("legal long logs must report zero failures, got %d", failures)
370		}
371		results := decodeResults(t, out.Bytes())
372		if len(results) != 1 || results[0]["line"] != float64(1) || results[0]["ok"] != true {
373			t.Fatalf("the long log must be one successful result in physical line order: %#v", results)
374		}
375		event := eventOf(t, results[0])
376		if event["action"] != "long-a" {
377			t.Fatalf("long event must keep its action, got %#v", event)
378		}
379		extra, ok := event["extra"].(map[string]any)
380		if !ok {
381			t.Fatalf("long extension field must survive as event.extra, got %#v", event)
382		}
383		pad, _ := extra["pad"].(string)
384		if pad != strings.Repeat("p", 5000) {
385			t.Fatalf("extension evidence must be preserved verbatim, got pad length %d", len(pad))
386		}
387	}
388	
389	// Under the source-CIDR filter the same rules hold: a long out-of-network
390	// event is not written at all and cannot trip the output fault, a long
391	// admitted event obeys the nil-error short-write stop, and full delivery
392	// preserves its normalized content and extension evidence.
393	func TestNormalizeIOFilteredLongResultShortWrite(t *testing.T) {
394		f, err := ParseSourceCIDRFilter("192.0.2.0/24")
395		if err != nil {
396			t.Fatal(err)
397		}
398		filter := &f
399		inNet := bigSourcedLog("in-big", "192.0.2.10")
400		outNet := bigSourcedLog("out-big", "198.51.100.20")
401	
402		t.Run("long out-of-network event never touches a broken output", func(t *testing.T) {
403			w := &nilErrorPrefixWriter{allowBytes: 0}
404			failures, err := NormalizeReaderFiltered(strings.NewReader(outNet+"\n"), w, filter)
405			if err != nil {
406				t.Fatalf("a filtered-out event must not be written, so its length cannot cause a write fault, got %v", err)
407			}
408			if failures != 0 || w.writes != 0 || w.buf.Len() != 0 {
409				t.Fatalf("filtered-out long event must leave no output, no failures and no write attempts, got failures=%d writes=%d bytes=%d",
410					failures, w.writes, w.buf.Len())
411			}
412		})
413	
414		t.Run("long admitted event, zero bytes accepted", func(t *testing.T) {
415			w := &nilErrorPrefixWriter{allowBytes: 0}
416			failures, err := NormalizeReaderFiltered(strings.NewReader(inNet+"\n"), w, filter)
417			expectLongShortWriteFailure(t, w, failures, 0, 1, err)
418			if w.buf.Len() != 0 {
419				t.Fatalf("zero acknowledged bytes must leave zero output, got %q", w.buf.String())
420			}
421		})
422	
423		t.Run("long admitted event, prefix accepted", func(t *testing.T) {
424			var healthy bytes.Buffer
425			if _, err := NormalizeReaderFiltered(strings.NewReader(inNet+"\n"), &healthy, filter); err != nil {
426				t.Fatalf("test setup: healthy filtered reference run failed: %v", err)
427			}
428			w := &nilErrorPrefixWriter{allowBytes: 120}
429			failures, err := NormalizeReaderFiltered(strings.NewReader(inNet+"\n"), w, filter)
430			expectLongShortWriteFailure(t, w, failures, 0, 1, err)
431			if w.buf.Len() != 120 {
432				t.Fatalf("exactly the acknowledged prefix must remain, got %d", w.buf.Len())
433			}
434			if !bytes.HasPrefix(healthy.Bytes(), w.buf.Bytes()) {
435				t.Fatalf("accepted bytes must be the unmodified prefix of healthy filtered output:\nkept:    %q\nhealthy: %q", w.buf.String(), healthy.String())
436			}
437		})
438	
439		t.Run("long admitted event fully delivered with evidence, out-of-network one silent", func(t *testing.T) {
440			var out bytes.Buffer
441			failures, err := NormalizeReaderFiltered(strings.NewReader(outNet+"\n"+inNet+"\n"), &out, filter)
442			if err != nil {
443				t.Fatalf("healthy delivery must complete with nil error, got %v", err)
444			}
445			if failures != 0 {
446				t.Fatalf("both logs are legal; filtering does not count failures, got %d", failures)
447			}
448			results := decodeResults(t, out.Bytes())
449			if len(results) != 1 || results[0]["line"] != float64(2) || results[0]["ok"] != true {
450				t.Fatalf("only the admitted physical line 2 must be emitted, got %#v", results)
451			}
452			event := eventOf(t, results[0])
453			if event["action"] != "in-big" || event["source_ip"] != "192.0.2.10" {
454				t.Fatalf("admitted long event mismatch: %#v", event)
455			}
456			extra, ok := event["extra"].(map[string]any)
457			if !ok {
458				t.Fatalf("extension evidence must survive under the filter, got %#v", event)
459			}
460			pad, _ := extra["pad"].(string)
461			if pad != strings.Repeat("p", 5000) {
462				t.Fatalf("extension evidence must be preserved verbatim, got pad length %d", len(pad))
463			}
464			if bytes.Contains(out.Bytes(), []byte("out-big")) {
465				t.Fatalf("the out-of-network long event must leave no trace: %q", out.String())
466			}
467		})
468	}
